import { useSyncExternalStore } from 'react';
import { cartStore } from './cartStore';

export function useCartCount() {
  const subscribe = (onStoreChange) => {
    cartStore.listeners.add(onStoreChange);
    return () => cartStore.listeners.delete(onStoreChange);
  };

  return useSyncExternalStore(
    subscribe,
    () => cartStore.count,
    () => 0
  );
}

referenceAnswer.en:
Hoist `subscribe` to module scope so its identity is stable:

```jsx
function subscribe(onStoreChange) {
  cartStore.listeners.add(onStoreChange);
  return () => cartStore.listeners.delete(onStoreChange);
}

const getSnapshot = () => cartStore.count;
const getServerSnapshot = () => 0;

export function useCartCount() {
  return useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot);
}
```

When `subscribe` depends on something from the component, wrap it in `useCallback` with exactly that dependency instead. React tears down and re-creates the subscription every time the function changes, so an inline definition turns each render into listener churn — cheap with a `Set`, expensive with a store that replays, debounces or opens a socket on subscribe. `getSnapshot` is fine here because it returns a number; returning a freshly built object instead would fail the `Object.is` check and loop forever.

referenceAnswer.ru:
Поднимите `subscribe` на уровень модуля, чтобы ссылка на него была стабильной:

```jsx
function subscribe(onStoreChange) {
  cartStore.listeners.add(onStoreChange);
  return () => cartStore.listeners.delete(onStoreChange);
}

const getSnapshot = () => cartStore.count;
const getServerSnapshot = () => 0;

export function useCartCount() {
  return useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot);
}
```

Если `subscribe` зависит от чего-то из компонента, вместо этого оберните его в `useCallback` ровно с этой зависимостью. React разрывает и создаёт подписку заново при каждом изменении функции, поэтому определение прямо в рендере превращает каждый рендер в перерегистрацию слушателей — дёшево с `Set`, дорого со стором, который при подписке переигрывает события, делает debounce или открывает сокет. `getSnapshot` здесь в порядке, потому что возвращает число; возврат заново собранного объекта не прошёл бы проверку `Object.is` и зациклился бы навсегда.

